import { z } from 'zod';
import { PersonaStatus, Platform } from './enums';

/**
 * The full identity of an alter ego. This is THE persona context: every AI workflow
 * receives it so content stays consistent. Generated by the Persona Agent, editable by the user.
 */
export const PersonaIdentity = z.object({
  name: z.string().min(1),
  handle: z.string().min(1).describe('Social handle without the @'),
  tagline: z.string(),
  ageRange: z.string().describe('e.g. "27-32"'),
  location: z.string(),
  occupation: z.string(),
  background: z.string().describe('Fictional backstory, 2-4 sentences'),
  biography: z.string().describe('Long-form bio, 1-2 paragraphs'),
  personalityTraits: z.array(z.string()).min(1),
  interests: z.array(z.string()),
  lifestyle: z.string(),
  goals: z.array(z.string()),
  communicationStyle: z.string(),
  writingTone: z.string(),
  writingStyleGuide: z.object({
    do: z.array(z.string()),
    dont: z.array(z.string()),
    signaturePhrases: z.array(z.string()),
    emojiUsage: z.string(),
  }),
  contentPillars: z.array(z.object({ name: z.string(), description: z.string() })).min(1),
  visualIdentity: z.object({
    aesthetic: z.string(),
    palette: z.array(z.string()),
    recurringSettings: z.array(z.string()),
    wardrobe: z.string(),
    photographyStyle: z.string(),
  }),
  socialBios: z.object({
    instagram: z.string(),
    tiktok: z.string(),
    youtube_shorts: z.string(),
    x: z.string(),
  }),
  examplePosts: z.array(z.object({ platform: Platform, text: z.string() })),
});
export type PersonaIdentity = z.infer<typeof PersonaIdentity>;

/** A trained likeness of the user at an image/video provider (e.g. Higgsfield Soul ID). */
export const CharacterRef = z.object({
  id: z.string().nullable(),
  status: z.enum(['training', 'ready', 'failed']),
  error: z.string().nullable().default(null),
  updatedAt: z.string(),
});
export type CharacterRef = z.infer<typeof CharacterRef>;

/** A persona row as returned by the API. */
export const Persona = z.object({
  id: z.uuid(),
  userId: z.uuid(),
  name: z.string(),
  handle: z.string().nullable(),
  tagline: z.string().nullable(),
  description: z.string().describe('The short prompt the user typed'),
  archetypeId: z.uuid().nullable(),
  status: PersonaStatus,
  identity: PersonaIdentity.nullable(),
  currentVersion: z.number().int(),
  avatarUrl: z.string().nullable(),
  /** keyed by provider, e.g. { higgsfield: {...} } */
  characterRefs: z.record(z.string(), CharacterRef),
  createdAt: z.string(),
  updatedAt: z.string(),
});
export type Persona = z.infer<typeof Persona>;

export const PersonaVersion = z.object({
  id: z.uuid(),
  personaId: z.uuid(),
  version: z.number().int(),
  identity: PersonaIdentity,
  changeNote: z.string().nullable(),
  createdAt: z.string(),
});
export type PersonaVersion = z.infer<typeof PersonaVersion>;
